<script setup lang="ts">import type{CollectorRank}from '@/types/dashboard';defineProps<{items:CollectorRank[];loading:boolean;period:string;rankBy:string}>();const emit=defineEmits<{period:[v:string];rank:[v:string]}>();const money=(v:number)=>new Intl.NumberFormat('vi-VN',{notation:'compact',maximumFractionDigits:1}).format(v)</script>
<template><v-card class="pa-4 pa-md-5 h-100" border rounded="xl"><div class="d-flex justify-space-between ga-3 mb-4"><div><div class="text-h6 font-weight-bold">Top nhân viên thu</div><div class="text-caption text-medium-emphasis">Xếp hạng hiệu quả thu phí</div></div><v-icon icon="mdi-trophy-outline" color="warning" /></div><div class="d-flex flex-wrap ga-2 mb-4"><v-btn-toggle :model-value="period" density="compact" mandatory color="primary" @update:model-value="emit('period',$event)"><v-btn value="today">Hôm nay</v-btn><v-btn value="month">Tháng</v-btn><v-btn value="quarter">Quý</v-btn></v-btn-toggle><v-select :model-value="rankBy" :items="[{title:'Theo doanh thu',value:'revenue'},{title:'Theo tỷ lệ',value:'completion'}]" density="compact" hide-details max-width="170" @update:model-value="emit('rank',$event)" /></div><v-skeleton-loader v-if="loading" type="list-item-avatar-three-line@4"/><div v-else-if="!items.length" class="empty-state">Chưa có dữ liệu nhân viên</div><div v-else><div v-for="item in items" :key="item.id||item.name" class="collector-row"><div class="collector-rank" :class="`collector-rank--${item.rank}`">{{ item.rank }}</div><v-avatar size="38" color="primary" variant="tonal" :image="item.avatar_url||undefined">{{ !item.avatar_url?item.name[0]:'' }}</v-avatar><div class="flex-grow-1 min-width-0"><div class="d-flex justify-space-between ga-2"><strong class="text-truncate">{{ item.name }}</strong><span class="text-success font-weight-bold">{{ money(item.revenue) }} ₫</span></div><div class="text-caption text-medium-emphasis">{{ item.households }} hộ · {{ item.transactions }} giao dịch · {{ item.completion_rate }}%</div></div></div></div></v-card></template>
